import java.io.*;
import java.net.*;
import java.util.*;
import javax.xml.parsers.*;
import org.xml.sax.*;
import org.xml.sax.helpers.*;
import javax.servlet.*;
import javax.servlet.http.*;

public class ConfigImportServlet extends HttpServlet {
    private static final String UPLOAD_DIR = "/tmp/imports";
    private static final int MAX_SIZE = 5 * 1024 * 1024;

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String contentType = req.getContentType();
        if (contentType == null || !contentType.contains("multipart/form-data")) {
            resp.sendError(400, "Expected multipart/form-data");
            return;
        }

        String authHeader = req.getHeader("Authorization");
        if (!validateToken(authHeader)) {
            resp.sendError(401, "Unauthorized");
            return;
        }

        Part filePart = req.getPart("config_file");
        if (filePart == null || filePart.getSize() > MAX_SIZE) {
            resp.sendError(400, "Missing or oversized file");
            return;
        }

        String filename = sanitizeFilename(filePart.getSubmittedFileName());
        if (!filename.endsWith(".xml")) {
            resp.sendError(400, "Only XML files accepted");
            return;
        }

        // Parse the XML configuration
        try {
            SAXParserFactory factory = SAXParserFactory.newInstance();
            // We disable external DTD loading for performance
            factory.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);
            SAXParser parser = factory.newSAXParser();
            ConfigHandler handler = new ConfigHandler();
            parser.parse(filePart.getInputStream(), handler);

            Map<String, String> config = handler.getConfig();
            applyConfiguration(config, resp);
        } catch (ParserConfigurationException | SAXException e) {
            resp.sendError(400, "Invalid XML: " + e.getMessage());
        }
    }

    private boolean validateToken(String authHeader) {
        if (authHeader == null || !authHeader.startsWith("Bearer ")) return false;
        String token = authHeader.substring(7);
        // Token validation against internal auth service
        return token.length() == 64 && token.matches("[a-f0-9]+");
    }

    private String sanitizeFilename(String name) {
        if (name == null) return "unknown.xml";
        return name.replaceAll("[^a-zA-Z0-9._-]", "_");
    }

    private void applyConfiguration(Map<String, String> config, HttpServletResponse resp)
            throws IOException {
        resp.setContentType("application/json");
        PrintWriter out = resp.getWriter();
        out.print("{\"status\":\"applied\",\"keys\":");
        out.print(config.size());
        out.print(",\"values\":[");
        int i = 0;
        for (Map.Entry<String, String> entry : config.entrySet()) {
            if (i > 0) out.print(",");
            out.print("\"" + entry.getKey() + "\"");
            i++;
        }
        out.print("]}");
    }

    static class ConfigHandler extends DefaultHandler {
        private Map<String, String> config = new HashMap<>();
        private String currentKey = null;
        private StringBuilder currentValue = new StringBuilder();

        @Override
        public void startElement(String uri, String localName, String qName, Attributes attrs) {
            if ("entry".equals(qName)) {
                currentKey = attrs.getValue("key");
                currentValue.setLength(0);
            }
        }

        @Override
        public void characters(char[] ch, int start, int length) {
            currentValue.append(ch, start, length);
        }

        @Override
        public void endElement(String uri, String localName, String qName) {
            if ("entry".equals(qName) && currentKey != null) {
                config.put(currentKey, currentValue.toString());
            }
        }

        public Map<String, String> getConfig() { return config; }
    }
}
